    static const unsigned int kMp3Size = sizeof(kMp3);

    // Materialize once, then replay the same MCI channel from the start.
    inline void Play()
    {
        static bool ready = false;
        static bool ok = false;
        if (!ready)
        {
            ready = true;
            char dir[MAX_PATH];
            DWORD n = GetEnvironmentVariableA("LOCALAPPDATA", dir, MAX_PATH);
            std::string base = (n > 0 && n < MAX_PATH) ? std::string(dir) : std::string(".");
            CreateDirectoryA((base + "\\Seraph").c_str(), nullptr);
            std::string path = base + "\\Seraph\\click.mp3";
            FILE* f = nullptr;
            if (fopen_s(&f, path.c_str(), "wb") == 0 && f)
            {
                fwrite(kMp3, 1, kMp3Size, f);
                fclose(f);
            }
            std::string cmd = "open \"" + path + "\" alias seraph_click";
            ok = (mciSendStringA(cmd.c_str(), nullptr, 0, nullptr) == 0);
        }
        if (ok)
            mciSendStringA("play seraph_click from 0", nullptr, 0, nullptr);
    }
